from dataclasses import dataclass

@dataclass(frozen=True)
class Money:
    amount: int  # stored in minor units (cents)
    currency: str

    def add(self, other: 'Money') -> 'Money':
        if self.currency != other.currency:
            raise ValueError(f"Currency mismatch: {self.currency} vs {other.currency}")
        return Money(self.amount + other.amount, self.currency)

    def multiply(self, factor: int) -> 'Money':
        return Money(self.amount * factor, self.currency)

# Usage — originals are never modified
price = Money(1000, 'USD')   # $10.00
tax   = Money(80, 'USD')     # $0.80
total = price.add(tax)        # new instance: $10.80
# price and tax are unchanged

@dataclass(frozen=True)
class Email:
    address: str

    def __post_init__(self):
        if not self.address:
            raise ValueError("Email address cannot be empty")
        local, _, domain = self.address.partition('@')
        if not local or not domain or '.' not in domain:
            raise ValueError(f"Invalid email address: {self.address}")

# This always works or raises immediately:
try:
    email = Email("user@example.com")   # valid
    bad   = Email("not-an-email")       # raises ValueError
except ValueError as e:
    print(e)  # "Invalid email address: not-an-email"

# Once you hold an Email, it is guaranteed to be valid.
# No defensive checks needed at call sites.

# Primitive obsession — all parameters are 'int', nothing stops wrong ordering
def transfer(amount: int, from_account_id: int, to_account_id: int) -> None:
    ...

# Caller can silently pass arguments in the wrong order:
transfer(account_a_id, account_b_id, amount)  # int, int, int — compiles fine, wrong semantics

# With value objects — wrong ordering is a type error:
@dataclass(frozen=True)
class Money:
    amount: int
    currency: str

@dataclass(frozen=True)
class AccountId:
    value: int

def transfer(amount: Money, from_account: AccountId, to_account: AccountId) -> None:
    ...

# Now swapping amount and account_id is caught by the type checker

from __future__ import annotations
from dataclasses import dataclass
from decimal import Decimal

@dataclass(frozen=True)
class Money:
    # Store in minor units (cents) as int to avoid floating-point errors
    amount_minor: int  # e.g. 1050 = $10.50
    currency: str      # ISO 4217 code: 'USD', 'EUR', 'GBP'

    def __post_init__(self):
        if not self.currency or len(self.currency) != 3:
            raise ValueError(f"Invalid ISO currency code: {self.currency}")
        # amount may be negative (representing debts/refunds)

    @staticmethod
    def of(amount: Decimal, currency: str) -> Money:
        """Factory accepting decimal dollars, e.g. Money.of(Decimal('10.50'), 'USD')"""
        return Money(int(amount * 100), currency)

    def add(self, other: Money) -> Money:
        self._assert_same_currency(other)
        return Money(self.amount_minor + other.amount_minor, self.currency)

    def subtract(self, other: Money) -> Money:
        self._assert_same_currency(other)
        return Money(self.amount_minor - other.amount_minor, self.currency)

    def multiply(self, factor: int) -> Money:
        return Money(self.amount_minor * factor, self.currency)

    def is_positive(self) -> bool:
        return self.amount_minor > 0

    def _assert_same_currency(self, other: Money) -> None:
        if self.currency != other.currency:
            raise ValueError(
                f"Cannot operate on {self.currency} and {other.currency}: use an exchange service"
            )

    def __repr__(self) -> str:
        major = self.amount_minor // 100
        minor = abs(self.amount_minor % 100)
        return f"{self.currency} {major}.{minor:02d}"

@dataclass(frozen=True)
class PostalCode:
    value: str

    def __post_init__(self):
        cleaned = self.value.replace(' ', '').upper()
        # simplified US ZIP + UK postcode validation
        if not (len(cleaned) in {5, 6, 7}):
            raise ValueError(f"Unrecognised postal code: {self.value}")
        object.__setattr__(self, 'value', cleaned)

@dataclass(frozen=True)
class CountryCode:
    value: str  # ISO 3166-1 alpha-2, e.g. 'US', 'GB'

    def __post_init__(self):
        if len(self.value) != 2 or not self.value.isalpha():
            raise ValueError(f"Invalid country code: {self.value}")
        object.__setattr__(self, 'value', self.value.upper())

@dataclass(frozen=True)
class Address:
    line1: str
    line2: str | None
    city: str
    postal_code: PostalCode   # VO inside VO
    country: CountryCode       # VO inside VO

    def __post_init__(self):
        if not self.line1 or not self.city:
            raise ValueError("Address requires at least line1 and city")

# Equality works across the entire composition:
a1 = Address('10 Downing St', None, 'London', PostalCode('SW1A2AA'), CountryCode('GB'))
a2 = Address('10 Downing St', None, 'London', PostalCode('SW1A2AA'), CountryCode('GB'))
assert a1 == a2  # True — structural equality all the way down

from dataclasses import dataclass
from typing import Dict

@dataclass(frozen=True)  # frozen=True enables __hash__
class DateRange:
    start: str  # ISO 8601 date string
    end: str

    def __post_init__(self):
        if self.end < self.start:
            raise ValueError("end must be >= start")

# Hotel pricing: rate per date range
room_rates: Dict[DateRange, int] = {
    DateRange('2026-12-24', '2026-12-26'): 45000,  # peak: $450/night in cents
    DateRange('2026-12-27', '2026-12-31'): 32000,  # shoulder: $320/night
}

# Lookup is safe because DateRange is immutable:
key = DateRange('2026-12-24', '2026-12-26')
print(room_rates[key])  # 45000 — works reliably

