# Before: primitive cluster — 'amount' and 'currency' always travel together
# but are not bound as a unit. Validation is scattered.
def create_invoice(customer_id: int, amount: int, currency: str, due_date: str) -> None:
    if amount <= 0:
        raise ValueError("Amount must be positive")
    if len(currency) != 3:
        raise ValueError("Invalid currency")
    # ... same checks repeated in calculate_tax, apply_discount, generate_receipt ...

def calculate_tax(amount: int, currency: str, rate: float) -> tuple[int, str]:
    if amount <= 0:          # duplicated check
        raise ValueError("Amount must be positive")
    return int(amount * rate), currency

# After: VO extraction — validation lives in one place
@dataclass(frozen=True)
class Money:
    amount_minor: int
    currency: str

    def __post_init__(self):
        if self.amount_minor <= 0:
            raise ValueError("Money amount must be positive")
        if len(self.currency) != 3:
            raise ValueError(f"Invalid ISO currency code: {self.currency}")

    def apply_rate(self, rate: float) -> 'Money':
        return Money(int(self.amount_minor * rate), self.currency)

def create_invoice(customer_id: int, total: Money, due_date: str) -> None:
    # Money is already validated — no defensive checks needed here
    ...

def calculate_tax(price: Money, rate: float) -> Money:
    return price.apply_rate(rate)  # clean, readable, no duplication

from dataclasses import dataclass
from uuid import UUID, uuid4

# Lightweight VO wrapping a UUID — entities use these as their ID type
@dataclass(frozen=True)
class UserId:
    value: UUID

    @staticmethod
    def generate() -> 'UserId':
        return UserId(uuid4())

    @staticmethod
    def from_str(s: str) -> 'UserId':
        try:
            return UserId(UUID(s))
        except ValueError:
            raise ValueError(f"Invalid UserId: {s!r}")

    def __str__(self) -> str:
        return str(self.value)

@dataclass(frozen=True)
class OrderId:
    value: UUID

    @staticmethod
    def generate() -> 'OrderId':
        return OrderId(uuid4())

# Without ID VOs — transposition error compiles and runs silently:
def ship_order(user_id: UUID, order_id: UUID) -> None: ...
ship_order(order_uuid, user_uuid)   # wrong order, no error

# With ID VOs — transposition error caught by type checker:
def ship_order(user_id: UserId, order_id: OrderId) -> None: ...
ship_order(OrderId.generate(), UserId.generate())  # mypy/pyright error: type mismatch
